#!/usr/bin/env bash
# PreToolUse: lockfiles are generated by bun / uv. Hand edits get overwritten or corrupt them.
set -euo pipefail

file="$(jq -r '.tool_input.file_path // empty')"
if [[ "$file" =~ (^|[/\\])(bun\.lock|uv\.lock)$ ]]; then
  printf 'Blocked: %s is generated. Run `bun install` (bun.lock) or `uv lock` (uv.lock) instead.\n' "$file" >&2
  exit 2
fi
